vec3 ComputeRay(vec2 coordUV)
{
    float fov = 60.0f;
    float side = tan(radians(fov*0.5f));

    float rayX = (coordUV.x*2.0f - 1.0f ) * side;
    float rayY = (coordUV.y*2.0f - 1.0f ) * side * iResolution.y/iResolution.x; 
    float z = 1.0;
    vec3 ray = normalize(vec3(rayX, rayY, z));
    return ray;
}

float hitSphere(vec3 rayOrigin, vec3 rayDirection, vec3 sphereOrigin, float radius){
    float a = dot(rayDirection,rayDirection);
    vec3 dir = rayOrigin - sphereOrigin;
    float b = 2.0f * dot(rayDirection,dir);
    float c = dot(dir,dir) - (radius * radius);
    float delta = b*b - 4.0f * a * c;
    if(delta < 0.0f){
        return -1.0f;
    }else if(delta == 0.0f){
        return -b / (2.0f*a);
    }else{
        return (-b - sqrt(delta))/(2.0f*a);
    }
}

vec3 rotate(vec3 v, float theta){
    float x = v.x * cos(theta) - v.z * sin(theta);
    float z = v.x * sin(theta) + v.z * cos(theta);
    return vec3(x,v.y,z);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord.xy/iResolution.xy;

    vec3 ray = ComputeRay(uv);

    float radius = 0.5f;
    vec3 sphere = vec3(0.0f,0.0f,2.0f);
    vec3 rayOrigin = vec3(0.0f,0.0f,0.0f);
    float intersect = hitSphere(rayOrigin,ray,sphere,radius);
    if(intersect > 0.0f){
        vec3 hitPoint = rayOrigin + intersect * ray;
        vec3 normal = normalize(hitPoint - sphere);
        vec3 lightDirection = normalize(vec3(1.0f,-1.0f,1.0f));
        lightDirection = normalize(rotate(lightDirection,iTime));
        vec3 lightAmbiantColor = vec3(1.0f,1.0f,1.0f);
        vec3 lightDiffuseColor = vec3(1.0f,1.0f,1.0f);
        vec3 lightSpecularColor = vec3(1.0f,1.0f,1.0f);

        vec3 materialAmbiantColor = vec3(0.0f,0.2f,0.2f);
        vec3 materialDiffuseColor = vec3(0.0f,1.0f,1.0f);
        vec3 materialSpecularColor = vec3(1.0f,1.0f,1.0f);
        vec3 viewDirection = normalize(rayOrigin - hitPoint);
        vec3 HalfDirection = normalize(-lightDirection + viewDirection);
        float diffuseFactor = max(dot(normal,-lightDirection),0.0f);
        float specularFactor = pow(max(dot(normal, HalfDirection),0.0f),32.0f);

        vec3 AmbiantColor = lightAmbiantColor * materialAmbiantColor;
        vec3 DiffuseColor = lightDiffuseColor * materialDiffuseColor * diffuseFactor;
        vec3 SpecularColor = lightSpecularColor * materialSpecularColor * specularFactor;



        fragColor = vec4(AmbiantColor+DiffuseColor+SpecularColor,1.0f);
    }else{
        fragColor = vec4(1.0f,0.0f,0.0f,1.0f);
    }


}
